#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/hmac.h>
#include <string>
#include <vector>
#include <cstring>
#include <mutex>
#include <unordered_map>
#include <chrono>
#include <memory>
#include <atomic>
#include <stdexcept>

namespace cloud_sdk {
namespace auth {

struct ServiceCredential {
    std::string service_id;
    std::string region;
    unsigned char master_key[32];
    uint64_t key_epoch;
};

class NonceDerivationContext {
public:
    NonceDerivationContext(const std::string& scope) : scope_(scope) {
        rotation_counter_ = 0;
    }

    void advance() { rotation_counter_++; }
    uint64_t counter() const { return rotation_counter_; }
    const std::string& scope() const { return scope_; }

private:
    std::string scope_;
    uint64_t rotation_counter_;
};

class DerivedKeyCache {
public:
    struct CacheEntry {
        unsigned char derived_key[32];
        unsigned char base_iv[12];
        std::atomic<uint64_t> uses;
        uint64_t max_uses;
    };

    bool lookup_and_increment(const std::string& key_id, CacheEntry*& out_ptr, uint64_t& assigned_counter) {
        std::lock_guard<std::mutex> lock(mu_);
        auto it = cache_.find(key_id);
        if (it != cache_.end()) {
            out_ptr = it->second.get();
            assigned_counter = out_ptr->uses.fetch_add(1);
            if (assigned_counter >= out_ptr->max_uses) {
                // Key exhausted, force re-derivation
                cache_.erase(it);
                return false;
            }
            return true;
        }
        return false;
    }

    void store(const std::string& key_id, std::unique_ptr<CacheEntry> entry) {
        std::lock_guard<std::mutex> lock(mu_);
        cache_[key_id] = std::move(entry);
    }

private:
    std::mutex mu_;
    std::unordered_map<std::string, std::unique_ptr<CacheEntry>> cache_;
};

class CrossServiceAuthenticator {
public:
    CrossServiceAuthenticator(const ServiceCredential& cred)
        : cred_(cred), nonce_ctx_("cross-service-auth") {
        key_cache_ = std::make_shared<DerivedKeyCache>();
    }

    // Derives a per-target encryption IV using HKDF-like construction
    // The IV incorporates the nonce context counter to prevent reuse
    std::vector<unsigned char> derive_iv_for_target(
            const std::string& target_service,
            const NonceDerivationContext& ctx) {
        unsigned char iv[12];
        // Derive IV from master key + target + counter
        unsigned char hmac_out[32];
        unsigned int hmac_len = 0;

        std::string label = target_service + ":" + ctx.scope() + ":" +
                           std::to_string(ctx.counter());

        if (HMAC(EVP_sha256(), cred_.master_key, 32,
             (unsigned char*)label.c_str(), label.size(),
             hmac_out, &hmac_len) == nullptr || hmac_len < 12) {
            throw std::runtime_error("HMAC computation failed during IV derivation");
        }

        // Truncate HMAC output to 12 bytes for GCM IV
        memcpy(iv, hmac_out, 12);

        return std::vector<unsigned char>(iv, iv + 12);
    }

    // Generate authentication token for cross-service call
    std::vector<unsigned char> generate_auth_token(
            const std::string& target_service,
            const std::string& payload) {

        std::string cache_key = cred_.service_id + ":" + target_service +
                               ":" + std::to_string(cred_.key_epoch);

        DerivedKeyCache::CacheEntry* entry_ptr = nullptr;
        uint64_t assigned_counter = 0;

        if (!key_cache_->lookup_and_increment(cache_key, entry_ptr, assigned_counter)) {
            // Derive a new key for this service pair
            auto new_entry = std::make_unique<DerivedKeyCache::CacheEntry>();
            derive_service_key(target_service, *new_entry);
            new_entry->uses.store(1);
            new_entry->max_uses = 1ULL << 32;
            assigned_counter = 0;
            key_cache_->store(cache_key, std::move(new_entry));
            // Re-lookup to get stable pointer
            key_cache_->lookup_and_increment(cache_key, entry_ptr, assigned_counter);
        }

        if (entry_ptr == nullptr) {
            throw std::runtime_error("Failed to obtain derived key cache entry");
        }

        // Compute IV: XOR base_iv with atomically-assigned counter
        unsigned char effective_iv[12];
        compute_effective_iv(entry_ptr->base_iv, assigned_counter, effective_iv);

        // Encrypt payload with AES-256-GCM
        std::vector<unsigned char> ciphertext(payload.size() + 16);
        int outlen = 0;
        int tmplen = 0;

        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        if (ctx == nullptr) {
            throw std::runtime_error("Failed to allocate cipher context");
        }

        if (EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), nullptr, nullptr, nullptr) != 1 ||
            EVP_EncryptInit_ex(ctx, nullptr, nullptr, entry_ptr->derived_key, effective_iv) != 1) {
            EVP_CIPHER_CTX_free(ctx);
            throw std::runtime_error("Failed to initialize AES-256-GCM encryption");
        }

        // AAD: service identifiers
        std::string aad = cred_.service_id + ":" + target_service;
        if (EVP_EncryptUpdate(ctx, nullptr, &outlen,
                         (unsigned char*)aad.c_str(), aad.size()) != 1) {
            EVP_CIPHER_CTX_free(ctx);
            throw std::runtime_error("Failed to process AAD");
        }

        if (EVP_EncryptUpdate(ctx, ciphertext.data(), &outlen,
                         (unsigned char*)payload.c_str(), payload.size()) != 1) {
            EVP_CIPHER_CTX_free(ctx);
            throw std::runtime_error("Encryption update failed");
        }
        int ct_len = outlen;

        if (EVP_EncryptFinal_ex(ctx, ciphertext.data() + ct_len, &tmplen) != 1) {
            EVP_CIPHER_CTX_free(ctx);
            throw std::runtime_error("Encryption finalization failed");
        }
        ct_len += tmplen;

        // Append GCM tag
        unsigned char tag[16];
        if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag) != 1) {
            EVP_CIPHER_CTX_free(ctx);
            throw std::runtime_error("Failed to retrieve GCM tag");
        }
        memcpy(ciphertext.data() + ct_len, tag, 16);

        EVP_CIPHER_CTX_free(ctx);
        ciphertext.resize(ct_len + 16);

        return ciphertext;
    }

private:
    void derive_service_key(const std::string& target,
                           DerivedKeyCache::CacheEntry& entry) {
        std::string info = "service-key:" + cred_.service_id + ":" + target;
        unsigned char prk[32];
        unsigned int prk_len;

        if (HMAC(EVP_sha256(), cred_.master_key, 32,
             (unsigned char*)info.c_str(), info.size(),
             prk, &prk_len) == nullptr || prk_len < 32) {
            throw std::runtime_error("HMAC computation failed during key derivation");
        }
        memcpy(entry.derived_key, prk, 32);

        // Derive base IV from the same PRK
        std::string iv_info = "iv:" + info;
        unsigned char iv_material[32];
        unsigned int iv_len;
        if (HMAC(EVP_sha256(), prk, 32,
             (unsigned char*)iv_info.c_str(), iv_info.size(),
             iv_material, &iv_len) == nullptr || iv_len < 12) {
            throw std::runtime_error("HMAC computation failed during base IV derivation");
        }
        memcpy(entry.base_iv, iv_material, 12);
    }

    void compute_effective_iv(const unsigned char* base_iv,
                             uint64_t counter,
                             unsigned char* out) {
        memcpy(out, base_iv, 12);
        // XOR counter into the last 8 bytes of IV
        // Counter is atomically assigned, guaranteeing uniqueness
        uint64_t ctr_be = __builtin_bswap64(counter);
        for (int i = 0; i < 8; i++) {
            out[4 + i] ^= ((unsigned char*)&ctr_be)[i];
        }
    }

    ServiceCredential cred_;
    NonceDerivationContext nonce_ctx_;
    std::shared_ptr<DerivedKeyCache> key_cache_;
};

} // namespace auth
} // namespace cloud_sdk
